import { expect, test, uniqueName } from "../../fixtures";

test("create a vendor", { tag: "@VEN-01" }, async ({ apiAs }) => {
  const member = await apiAs("member");
  const name = uniqueName("Acme Freight");

  const res = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
  });
  const body = await res.text();
  expect(res.status(), body).toBe(201);
  const vendor = JSON.parse(body);

  expect(vendor.name, body).toBe(name);
  expect(vendor.category, body).toBe("logistics");
  expect(vendor.contact_email, body).toBe("ops@acmefreight.example");
  expect(vendor.status, body).toBe("draft");

  await expect
    .poll(async () => {
      const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
      expect(audit.status(), await audit.text()).toBe(200);
      const trail = (await audit.json()) as { items: { action: string }[] };
      return trail.items.map((event) => event.action);
    })
    .toContain("vendor.created");
});
